def build_members(page):
    scripts='<link rel="stylesheet" href="/assets/membership.css"><script defer src="/assets/vendor/supabase-2.102.0.js"></script><script defer src="/assets/membership.js"></script>'
    nav='<nav class="member-nav"><a href="/account/">My account</a><a href="/premium/">Plans</a><a href="/analysis/members/">Premium library</a></nav><p id="member-status" class="member-status" role="status">Checking membership availability…</p><noscript>JavaScript is required for member accounts. Free guides remain available.</noscript>'
    auth='''<section id="auth-box" class="member-box" hidden><h2>Sign in or create an account</h2><form id="auth-form"><label>Email<input type="email" name="email" autocomplete="email" required></label><label>Password<input type="password" name="password" minlength="8" autocomplete="current-password" required></label><button class="button" name="action" value="login">Sign in</button><button class="button secondary" name="action" value="signup">Create account</button><button class="button secondary" name="action" value="reset" formnovalidate>Reset password</button></form></section><section id="session-box" hidden><p id="member-email"></p><button id="signout" class="button secondary">Sign out</button></section>'''
    page('/account/','Your Analysis membership','Manage your access and USDT payment submissions.',nav+auth+'''<section id="account-box" class="member-box" hidden><h2>Your access</h2><p id="access-status"></p><a class="button" href="/membership/checkout/">Choose a plan</a><h2>Your orders</h2><div id="order-list"></div><h2>Change password</h2><form id="password-form"><label>New password<input name="password" type="password" minlength="8" autocomplete="new-password" required></label><button class="button">Save password</button></form><a id="admin-link" href="/membership/admin/" hidden>Manage articles and payments →</a></section>''',scripts)
    page('/membership/checkout/','Analysis Premium · USDT','Monthly: 29 USDT. Annual: 204 USDT. Manual renewal; no automatic debit.',nav+auth+'''<section id="checkout-box" class="member-box" hidden><h2>Choose your access period</h2><p>Access begins after payment verification. Renewing early extends your existing expiry date.</p><form id="order-form"><label>Plan<select name="plan"><option value="monthly">1 month · 29 USDT</option><option value="annual">1 year · 204 USDT</option></select></label><button class="button">Create payment request</button></form><div id="payment-instructions" hidden><h2>Your payment request</h2><p id="order-details"></p><p>Send USDT on the <strong>TRC20 (Tron)</strong> network only. Ensure the recipient receives the full order amount after fees.</p><code id="payment-wallet"></code><button id="copy-wallet" class="button secondary">Copy address</button><p>No automatic debit. After sending, submit the transaction ID below. Access remains pending until the team verifies the token, destination and amount on-chain.</p><form id="tx-form"><label>Tron transaction ID<input name="txid" pattern="[a-fA-F0-9]{64}" minlength="64" maxlength="64" required></label><button class="button">Submit for verification</button></form></div></section><p>Payment questions: <a href="https://t.me/Raphael_TraderGoldFx">contact Raphael on Telegram</a>. Include your order ID. Do not send another payment while a request is pending.</p>''',scripts)
    page('/analysis/members/','Premium analysis library','Read previews and open the full articles included in an active Analysis membership.',nav+auth+'<div id="premium-library"></div><article id="premium-reader" class="member-box" hidden></article>',scripts)
    page('/membership/admin/','Membership administration','Review USDT payments and publish original analysis. Administrator access is required.',nav+auth+'''<section id="admin-box" hidden><div class="member-box"><h2>Payment review</h2><p>Check the linked Tron transaction: successful USDT transfer, correct TRC20 token, receiving wallet, full net amount and sufficient confirmations. A transaction ID alone is not proof of payment.</p><div id="review-list"></div></div><form id="article-form" class="member-box"><h2>Create or update an article</h2><p>Use the same slug to update an existing article. The full text is stored in the protected database.</p><label>Slug<input name="slug" pattern="[a-z0-9-]+" required></label><label>Title<input name="title" minlength="3" required></label><label>Public preview<textarea name="preview" minlength="10" required></textarea></label><label>Full article (plain text)<textarea name="body" rows="14" minlength="50" required></textarea></label><label><input name="published" type="checkbox">Publish</label><button class="button">Save article</button><div id="admin-articles"></div></form></section>''',scripts)
